];
const rows = [
  row('Nombre', esc(l.nombre)), row('Correo', `<a href="mailto:${esc(l.email)}" style="color:#1a73e8">${esc(l.email)}</a>`),
  row('WhatsApp / Tel', esc(l.telefono)), row('Empresa / web', esc(l.empresa || '—')), row('Ciudad / país', esc(l.ubicacion || '—')),
  row('Servicio', `<b>${esc(l.servicioInteres)}</b>`), row('Mensaje', esc(l.mensaje || '—')),
  row('Origen', `${esc(l.canal)}${l.campana ? ' · ' + esc(l.campana) : ''} · ${esc(l.idioma)}`), row('Página', esc(l.pagina)),
  row('Fecha', esc(l.fechaLocal || l.fecha)), row('ID', `<span style="color:#80868b">${esc(l.id)}</span>`),
];
const tip = l.leadCalificado
  ? `<b>Lead calificado.</b> Ahora está eligiendo hora en tu agenda. Si en 30 min no llega el correo “📅 Cita agendada”, escríbele por WhatsApp: los leads contactados en la primera hora cierran hasta 7× más.`
  : `<b>Pregunta general.</b> Respóndele hoy mismo por WhatsApp o correo y, si hay interés, mándale tu agenda: https://calendar.app.google/oCftwJiTxdSKTk3L7`;
return shell({ eyebrow: 'Nuevo lead · growthdigital.marketing', title: esc(l.nombre), subtitle: `${esc(l.servicioInteres)} · ${esc(l.ubicacion || 'Sin ciudad')}`, rows, buttons, tip, footer: 'Enviado por tu automatización n8n · Growth Digital · Medellín' });
})() }}
